const cases = [
  { question: "What were Nova Tech's total revenues for fiscal year 2025 according to the 10-K?", expected_contains: ["165.9"], category: "factual" },
  { question: "How much cash did Nova Tech have at year-end 2025?", expected_contains: ["45.2"], category: "factual" },
  { question: "Does management expect the Professional Services margin pressure to continue into 2026?", expected_contains: ["legacy", "wind"], category: "contextual" },
  { question: "Why did Nova Tech shift away from professional services work?", expected_contains: ["margin", "integrator"], category: "contextual" },
  { question: "What is the interest rate on the credit agreement?", expected_contains: [], category: "not_in_docs" }
];
return cases.map((c, i) => ({
  json: {
    ...c,
    chatInput: c.question,
    sessionId: 'eval-' + Date.now() + '-' + i
  }
}));

const refusals = ['cannot find', 'could not find', 'not find this information'];
const cases = $('Test Cases').all();
return $input.all().map((item, i) => {
  const tc = cases[i].json;
  const answer = String(item.json.output || item.json.response || item.json.text || '');
  const lower = answer.toLowerCase();
  const expected = tc.expected_contains || [];
  const hits = expected.filter(k => lower.includes(k.toLowerCase()));
  const contains_score = expected.length ? hits.length / expected.length : 0;
  const refused = refusals.some(r => lower.includes(r));
  const has_substantive_answer = answer.length > 50 && !refused;
  const pass = tc.category === 'not_in_docs'
    ? refused
    : contains_score >= 0.5 && has_substantive_answer;
  return { json: {
    question: tc.question,
    category: tc.category,
    contains_score,
    has_substantive_answer,
    refused,
    pass,
    answer
  }};
});

const results = $input.first().json.results;
const passed = results.filter(r => r.pass).length;
const byCat = {};
results.forEach(r => {
  byCat[r.category] = byCat[r.category] || { total: 0, passed: 0 };
  byCat[r.category].total++;
  if (r.pass) byCat[r.category].passed++;
});
const failed = results.filter(r => !r.pass).map(r => ({
  question: r.question,
  reason: r.category === 'not_in_docs' ? 'Did not decline to answer'
        : r.refused ? 'Agent said it could not find the information'
        : 'Keyword match below 50% (retrieval or wording miss)'
}));
return [{ json: {
  overall_pass_rate: `${Math.round(100 * passed / results.length)}% (${passed}/${results.length})`,
  by_category: byCat,
  failed
}}];
